161	/// * `v` - `v` value from the signature.
162	/// * `r` - `r` value from the signature.
163	/// * `s` - `s` value from the signature.
164	fn encode_calldata(hash: B256, v: u8, r: B256, s: B256) -> Vec<u8> {
165	    let calldata = EcRecoverData { hash, v, r, s };
166	    EcRecoverData::abi_encode(&calldata)
