169	/// Validates the `s` value of a signature.
170	///
171	/// EIP-2 still allows signature malleability for `ecRecover` precompile.
172	///
173	/// Remove this possibility and make the signature unique.
174	///
175	/// Appendix F in the [Ethereum Yellow paper], defines the valid range for s in
176	/// (301): 0 < s < secp256k1n ÷ 2 + 1, and for v in (302): v ∈ {27, 28}.
177	///
178	/// Most signatures from current libraries generate a unique signature
179	/// with an s-value in the lower half order.
180	///
181	/// If your library generates malleable signatures,
182	/// such as s-values in the upper range, calculate a new s-value
183	/// with 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141 -
184	/// s1, and flip v from 27 to 28 or vice versa.
185	///
186	/// If your library also generates signatures with 0/1 for v instead 27/28,
187	/// add 27 to v to accept these malleable signatures as well.
188	///
189	/// # Arguments
190	///
191	/// * `s` - `s` value from the signature.
192	///
193	/// # Errors
194	///
195	/// * [`Error::InvalidSignatureS`] - If the `s` value is greater than
196	///   [`SIGNATURE_S_UPPER_BOUND`].
197	///
198	/// [Ethereum Yellow paper]: https://ethereum.github.io/yellowpaper/paper.pdf
199	fn check_if_malleable(s: &B256) -> Result<(), Error> {
200	    let s_u256 = U256::from_be_slice(s.as_slice());
201	    if s_u256 > SIGNATURE_S_UPPER_BOUND {
202	        return Err(ECDSAInvalidSignatureS { s: *s }.into());
203	    }
204	    Ok(())
205	}
