105	/// Calls `ecRecover` EVM precompile.
106	///
107	/// The `ecRecover` EVM precompile allows for malleable (non-unique) signatures:
108	/// this function rejects them by requiring the `s` value to be in the lower
109	/// half order, and the `v` value to be either 27 or 28.
110	///
111	/// # Arguments
112	///
113	/// * `context` - Read access to the contract's host, used to make the static
114	///   call to the `ecRecover` precompile.
115	/// * `hash` - Hash of the message.
116	/// * `v` - `v` value from the signature.
117	/// * `r` - `r` value from the signature.
118	/// * `s` - `s` value from the signature.
119	///
120	/// # Errors
121	///
122	/// * [`Error::InvalidSignature`] - If the recovered address is
123	///   [`Address::ZERO`].
124	///
125	/// # Panics
126	///
127	/// * If the `ecRecover` precompile fails to execute.
128	fn _recover(
129	    context: &impl HostAccess<Host = VM>,
130	    hash: B256,
131	    v: u8,
132	    r: B256,
133	    s: B256,
134	) -> Result<Address, Error> {
135	    let calldata = encode_calldata(hash, v, r, s);
136	
137	    if v == 0 || v == 1 {
138	        // `ecRecover` panics for these values but following the Solidity tests
139	        // https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/test/utils/cryptography/ECDSA.test.js
140	        // it should return `ECDSAInvalidSignature` error.
141	        return Err(ECDSAInvalidSignature {}.into());
142	    }
143	
144	    let recovered =
145	        call::static_call(context.vm(), Call::new(), ECRECOVER_ADDR, &calldata)
146	            .expect("should call `ecRecover` precompile");
147	
148	    let recovered = Address::from_slice(&recovered[12..]);
149	
150	    if recovered.is_zero() {
151	        return Err(ECDSAInvalidSignature {}.into());
152	    }
153	    Ok(recovered)
154	}
