5	/// Address of the `P256VERIFY` EVM precompile as per [RIP-7212].
6	///
7	/// [RIP-7212]: https://github.com/ethereum/RIPs/blob/723155c3d86427412b5bc0f98ad1e4791ea7347f/RIPS/rip-7212.md
8	pub const P256_VERIFY_ADDRESS: Address =
9	    address!("0x0000000000000000000000000000000000000100");
10	
11	/// N/2 for excluding higher order `s` values, where
12	/// N is subgroup order (number of points).
13	pub(crate) const HALF_N: U256 = uint!(
14	    0x7fffffff800000007fffffffffffffffde737d56d38bcf4279dce5617e3192a8_U256
15	);
16	
17	pub(crate) fn p256_verify(
18	    context: &impl HostAccess<Host = VM>,
19	    hash: B256,
20	    r: B256,
21	    s: B256,
22	    x: B256,
23	    y: B256,
24	) -> bool {
25	    // enforce low-`s` values to disallow malleability where (`r`, `s`) and
26	    // (`r`, `n - s`) are both valid.
27	    if U256::from_be_bytes(s.0) > HALF_N {
28	        return false;
29	    }
30	
31	    // concatenate the input into the expected 160 bytes format
32	    let data = (hash, r, s, x, y).abi_encode();
33	
34	    let result = call::static_call(
35	        context.vm(),
36	        Call::new(),
37	        P256_VERIFY_ADDRESS,
38	        &data,
39	    )
40	    .expect("P256VERIFY precompile should not fail");
41	
42	    // `P256VERIFY` returns an encoded boolean `true` for a successful
43	    // verification and an empty vector on a failed verification
44	    !result.is_empty()
45	}
