1	//! [EIP-712](https://eips.ethereum.org/EIPS/eip-712) is a standard for hashing
2	//! and signing typed structured data.
3	//!
4	//! The implementation of the domain separator was designed to be as efficient
5	//! as possible while still properly updating the chain id to protect against
6	//! replay attacks on an eventual fork of the chain.
7	//!
8	//! NOTE: This contract implements the version of the encoding known as "v4", as
9	//! implemented by the JSON RPC method [`eth_signTypedDataV4`] in `MetaMask`.
10	//!
11	//! [`eth_signTypedDataV4`]: https://docs.metamask.io/guide/signing-data.html
12	
13	use alloc::{borrow::ToOwned, string::String, vec::Vec};
14	
15	use alloy_primitives::{keccak256, Address, B256, U256};
16	use alloy_sol_types::{sol, SolType};
17	use stylus_sdk::prelude::{AccountAccess, ChainAccess, HostAccess};
18	
19	/// Keccak-256 hash of the EIP-712 domain separator type string.
20	const TYPE_HASH: [u8; 32] =
21	    keccak_const::Keccak256::new()
22	        .update(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
23	        .finalize();
24	
25	/// Field for the domain separator.
26	const FIELDS: [u8; 1] = [0x0f];
27	
28	/// Salt for the domain separator.
29	const SALT: [u8; 32] = [0u8; 32];
30	
31	/// Prefix for ERC-191 version with `0x01`.
32	const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];
33	
34	/// Tuple for the domain separator.
35	type DomainSeparatorTuple = sol! {
36	    tuple(bytes32, bytes32, bytes32, uint256, address)
37	};
38	
39	/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
40	/// `0x01`).
41	///
42	/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
43	/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
44	/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
45	/// part of EIP-712.
46	///
47	/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
48	#[must_use]
49	pub fn to_typed_data_hash(
50	    domain_separator: &[u8; 32],
51	    struct_hash: &[u8; 32],
52	) -> B256 {
53	    let mut preimage = [0u8; 66];
54	    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
55	    preimage[2..34].copy_from_slice(domain_separator);
56	    preimage[34..].copy_from_slice(struct_hash);
57	    keccak256(preimage)
58	}
