60	/// EIP-712 Contract interface.
61	///
62	/// The chain id and the contract's address are read from the host, so
63	/// implementors must give access to it through [`HostAccess`] (which every
64	/// `#[storage]` type already does).
65	pub trait IEip712: HostAccess {
66	    /// Immutable name of EIP-712 instance.
67	    const NAME: &'static str;
68	    /// Hashed name of EIP-712 instance.
69	    const HASHED_NAME: [u8; 32] =
70	        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();
71	
72	    /// Immutable version of EIP-712 instance.
73	    const VERSION: &'static str;
74	    /// Hashed version of EIP-712 instance.
75	    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
76	        .update(Self::VERSION.as_bytes())
77	        .finalize();
78	
79	    /// Returns chain id.
80	    ///
81	    /// # Arguments
82	    ///
83	    /// * `&self` - Read access to the contract's state.
84	    #[must_use]
85	    fn chain_id(&self) -> U256 {
86	        U256::from(self.vm().chain_id())
87	    }
88	
89	    /// Returns the contract's address.
90	    ///
91	    /// # Arguments
92	    ///
93	    /// * `&self` - Read access to the contract's state.
94	    #[must_use]
95	    fn contract_address(&self) -> Address {
96	        self.vm().contract_address()
97	    }
98	
99	    /// Returns the fields and values that describe the domain separator used by
100	    /// this contract for EIP-712 signature.
101	    ///
102	    /// # Arguments
103	    ///
104	    /// * `&self` - Read access to the contract's state.
105	    fn eip712_domain(
106	        &self,
107	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
108	        (
109	            FIELDS,
110	            Self::NAME.to_owned(),
111	            Self::VERSION.to_owned(),
112	            self.chain_id(),
113	            self.contract_address(),
114	            SALT,
115	            Vec::new(),
116	        )
117	    }
118	
119	    /// Returns the domain separator for the current chain.
120	    ///
121	    /// # Arguments
122	    ///
123	    /// * `&self` - Read access to the contract's state.
124	    fn domain_separator_v4(&self) -> B256 {
125	        let encoded = DomainSeparatorTuple::abi_encode(&(
126	            TYPE_HASH,
127	            Self::HASHED_NAME,
128	            Self::HASHED_VERSION,
129	            self.chain_id(),
130	            self.contract_address(),
131	        ));
132	
133	        keccak256(encoded)
134	    }
135	
136	    /// Given an already [hashed struct], this function returns the hash of the
137	    /// fully encoded EIP-712 message for this domain.
138	    ///
139	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
140	    ///
141	    /// # Arguments
142	    ///
