44	/// State of a [`Nonces`] Contract.
45	#[storage]
46	pub struct Nonces {
47	    /// Mapping from address to its nonce.
48	    pub(crate) nonces: StorageMap<Address, StorageU256>,
49	}
50	
51	/// Interface for [`Nonces`]
52	#[public]
53	// The `#[public]` macro adds an undocumented helper method to the trait.
54	#[allow(missing_docs)]
55	pub trait INonces {
56	    /// Returns the unused nonce for the given account.
57	    ///
58	    /// # Arguments
59	    ///
60	    /// * `&self` - Read access to the contract's state.
61	    /// * `owner` - The address for which to return the nonce.
62	    #[must_use]
63	    fn nonces(&self, owner: Address) -> U256;
64	}
65	
66	#[public]
67	#[implements(INonces)]
68	impl Nonces {}
69	
70	#[public]
71	impl INonces for Nonces {
72	    fn nonces(&self, owner: Address) -> U256 {
73	        self.nonces.get(owner)
74	    }
75	}
76	
77	impl Nonces {
78	    /// Consumes a nonce for the given `account`.
79	    ///
80	    /// # Arguments
81	    ///
82	    /// * `&mut self` - Write access to the contract's state.
83	    /// * `owner` - The address for which to consume the nonce.
84	    ///
85	    /// # Panics
86	    ///
87	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
88	    pub fn use_nonce(&mut self, owner: Address) -> U256 {
89	        let nonce = self.nonces.get(owner);
90	
91	        self.nonces
92	            .setter(owner)
93	            .add_assign_checked(ONE, "nonce should not exceed `U256::MAX`");
94	
95	        nonce
96	    }
97	
98	    /// Same as `use_nonce` but checking that the `nonce` is the next valid for
99	    /// the owner.
100	    ///
101	    /// # Arguments
102	    ///
103	    /// * `&mut self` - Write access to the contract's state.
104	    /// * `owner` - The address for which to consume the nonce.
105	    /// * `nonce` - The nonce to consume.
106	    ///
107	    /// # Errors
108	    ///
109	    /// * [`Error::InvalidAccountNonce`] - Returns an error if the `nonce` is
110	    ///   not the next valid nonce for the owner.
111	    ///
112	    /// # Panics
113	    ///
114	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
115	    pub fn use_checked_nonce(
116	        &mut self,
117	        owner: Address,
118	        nonce: U256,
119	    ) -> Result<(), Error> {
120	        let current_nonce = self.use_nonce(owner);
121	
122	        if nonce != current_nonce {
123	            return Err(Error::InvalidAccountNonce(InvalidAccountNonce {
124	                account: owner,
125	                current_nonce,
126	            }));
127	        }
128	
129	        Ok(())
130	    }
131	}
